-- 让一个携带 CanvasGroup 组件的 ui元素 慢慢显示和隐藏; 非常实用


---@class IdolLive3D_UISmoothShowEnt           
local IdolLive3D_UISmoothShowEnt = Class('IdolLive3D_UISmoothShowEnt')

-- 外部访问时使用:
-- ---@type IdolLive3D_UISmoothShowEnt
-- local IdolLive3D_UISmoothShowEnt = import('Game.IdolLive3D.IdolLive3D_UISmoothShowEnt')



-- ========================================================

--- lua:
local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程

---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject
local Mathf = CS.UnityEngine.Mathf
local Vector3 = CS.UnityEngine.Vector3
local CanvasGroup = CS.UnityEngine.CanvasGroup
local Time = CS.UnityEngine.Time

--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool


-- ========================================================


---@param go_ UnityEngine.GameObject
---@param isActive_ boolean 可用此 bool 来永久隐藏 go
---@param initIsShow_ boolean          @ 在开局的一瞬间, go是否显示
---@param initTargetIsShow_ boolean     @ 在开局之后, go变化的第一个目标是 显示还是隐藏
---@param interactableThreshold_ number @ [0.0,1.0] 当 alpha 大于多少值时, 会开启 CanvasGroup 的 interactable; 比如 0.9
---@param curveLevel_ number @ int, {1,2,3} 一阶/二阶/三阶曲线
function IdolLive3D_UISmoothShowEnt:__init( go_, isActive_, initIsShow_, initTargetIsShow_, interactableThreshold_, curveLevel_ )
    self.go = go_
    self.isActive = isActive_

    if self.isActive == false then 
        KTool.SetActive(self.go, false )
        return
    end     

    self.canvasGroup = KTool.GetComponent(go_, typeof(CanvasGroup))
    assert( isNotNull(self.canvasGroup) )
    ---
    self.lastAlpha = initIsShow_==true and 1.0 or 0.0
    CfUtils.SetCanvasGroupAlpha( self.go, self.lastAlpha )
    self.tgtIsShow = initTargetIsShow_
    self.interactableThreshold = checkNumber(interactableThreshold_)
    ---
    self.startTime = Time.time
    self.endTime = self.startTime
    --- 
    if curveLevel_~=1 and curveLevel_~=2 and curveLevel_~=3 then 
        printError( "参数 curveLevel_ 异常, 现将其设为 1" )
        curveLevel_ = 1
    end
    self.curveLevel = curveLevel_
end




-- 需手动调用 Delete()
function IdolLive3D_UISmoothShowEnt:__delete()
end




function IdolLive3D_UISmoothShowEnt:SelfUpdate()
    if self.isActive == false then 
        return
    end  
    if Time.time > self.endTime + 1 then -- 冗余时间留长点
        return
    end 
    ---
    local t = Mathf.Clamp01((Time.time - self.startTime) / (self.endTime - self.startTime)) -- [0,1]
    local curve_t = self:_GetCurveT(t)

    local a =  KTool.Remap( 0, 1, self.lastAlpha, self.tgtIsShow==true and 1 or 0, curve_t )


    CfUtils.SetCanvasGroupAlpha( self.go, a )

    if self.canvasGroup.interactable ~= self.tgtIsShow then 
        if self.tgtIsShow == true and t > self.interactableThreshold then 
            CfUtils.SetCanvasGroupInteractable( self.go, self.tgtIsShow )
            --printError( "切换 -1- " .. tostring(self.tgtIsShow) ) 
        elseif self.tgtIsShow == false and t < self.interactableThreshold then  
            CfUtils.SetCanvasGroupInteractable( self.go, self.tgtIsShow )
            --printError( "切换 -2- " .. tostring(self.tgtIsShow) )
        end 
    end 
end



function IdolLive3D_UISmoothShowEnt:SetShowOrHide( isShow_, duration_ )
    if self.isActive == false then 
        return
    end 
    if self.go.activeSelf == false then 
        KTool.SetActive( self.go, true )
    end     

    ---
    self.lastAlpha = self.tgtIsShow==true and 1.0 or 0.0

    self.tgtIsShow = isShow_
    self.startTime = Time.time
    self.endTime = self.startTime + duration_
end



----------------------------------------------------------

function IdolLive3D_UISmoothShowEnt:_GetCurveT(t_)
    if self.curveLevel == 2 then 
        return t_ * t_
    elseif self.curveLevel == 3 then
        return t_ * t_ * t_
    else
        return t_
    end
end


return IdolLive3D_UISmoothShowEnt
